# Strict first-KDIGO3 primary mortality outcomes.
# Uses strictK3_primary/data/ccw_final.rds generated by the strictK3 CCW/IPCW
# runner. Outputs compact CSV/Markdown results without touching legacy outputs.
suppressPackageStartupMessages({
  library(dplyr)
  library(readr)
  library(survival)
  library(DBI)
  library(RPostgres)
})

set.seed(20260715)

root_dir <- Sys.getenv("CRRT_ANALYSIS_ROOT")
data_dir <- file.path(Sys.getenv("CRRT_WORKSPACE_ROOT"), "09_工作稿/out/run20/NEW/v1/data")
out_dir <- file.path(Sys.getenv("CRRT_WORKSPACE_ROOT"), "09_工作稿/out/run20/NEW/v1/results")
dir.create(out_dir, showWarnings = FALSE, recursive = TRUE)

ccw <- readRDS(file.path(data_dir, "ccw_final.rds")) %>%
  distinct(clone_id, .keep_all = TRUE) %>%
  mutate(
    trt = as.integer(strategy == "A_early"),
    strategy_label = if_else(strategy == "A_early", "Early CRRT", "Deferred CRRT")
  )

# ===== RUN-20 · CH-01 最小改动：只重定义结局两列（died_28d / follow_time_28d）=====
# 注意：本脚本模型消费的是 follow_days/event（由 03_ccw_ipcw.R L61-66 从两列导出），
# 故必须用同一条公式重导（run14 教训：只改两列会静默失效）。
cat("[RUN-20 scope] v1 ccw cols has protocol_censor_h:", "protocol_censor_h" %in% names(ccw), "\n")
con20 <- DBI::dbConnect(RPostgres::Postgres(), host = "localhost", port = 5432,
                        dbname = "mimiciv31", user = "postgres", password = Sys.getenv("PGPASSWORD"))
ch01_dod <- DBI::dbGetQuery(con20, "SELECT subject_id, dod FROM mimiciv_hosp.patients") %>% mutate(dod = as.Date(dod))
DBI::dbDisconnect(con20)
cat("[RUN-20 check] v1 died_28d OLD (unique stays):", length(unique(ccw$stay_id[ccw$died_28d %in% TRUE])), "\n")
ccw <- ccw %>%
  left_join(ch01_dod, by = "subject_id") %>%
  mutate(
    .t0 = as.POSIXct(t0, tz = "UTC"),
    .dt = as.POSIXct(deathtime, tz = "UTC"),
    .dc = coalesce(as.numeric(difftime(.dt, .t0, units = "days")), as.numeric(dod - as.Date(.t0))),
    died_28d        = !is.na(.dc) & .dc >= 0 & .dc <= 28,
    follow_time_28d = pmin(28, ifelse(is.na(.dc), 28, .dc))
  ) %>%
  select(-.dc, -.t0, -.dt, -dod) %>%
  mutate(
    follow_h    = pmin(follow_time_28d * 24, coalesce(protocol_censor_h, follow_time_28d * 24)),
    follow_days = follow_h / 24,
    event = died_28d & (is.na(protocol_censor_h) | follow_time_28d * 24 < protocol_censor_h)
  )
cat("[RUN-20 check] v1 died_28d NEW (unique stays):", length(unique(ccw$stay_id[ccw$died_28d %in% TRUE])), "\n")

rmst_wkm <- function(times, events, weights, tau = 28) {
  fit <- survfit(Surv(times, events) ~ 1, weights = weights)
  t <- c(0, fit$time)
  s <- c(1, fit$surv)
  if (max(t, na.rm = TRUE) < tau) {
    t <- c(t, tau)
    s <- c(s, s[length(s)])
  } else {
    idx <- max(which(t <= tau))
    t <- c(t[seq_len(idx)], tau)
    s <- c(s[seq_len(idx)], s[idx])
  }
  keep <- !duplicated(t)
  t <- t[keep]
  s <- s[keep]
  sum(diff(t) * s[-length(s)])
}

boot_rmst_diff <- function(data, B = 1000, tau = 28) {
  ids <- unique(data$stay_id)
  n <- length(ids)
  dA <- data[data$strategy == "A_early", c("stay_id", "follow_days", "event", "ipcw_w_trim")]
  dB <- data[data$strategy == "B_deferred", c("stay_id", "follow_days", "event", "ipcw_w_trim")]
  diffs <- replicate(B, {
    samp <- data.frame(stay_id = sample(ids, n, replace = TRUE))
    sA <- merge(samp, dA, by = "stay_id", all.x = TRUE)
    sB <- merge(samp, dB, by = "stay_id", all.x = TRUE)
    tryCatch(
      rmst_wkm(sA$follow_days, sA$event, sA$ipcw_w_trim, tau) -
        rmst_wkm(sB$follow_days, sB$event, sB$ipcw_w_trim, tau),
      error = function(e) NA_real_
    )
  })
  diffs <- diffs[is.finite(diffs)]
  c(
    rmst_diff_boot_mean = mean(diffs),
    rmst_diff_ci_lower = unname(quantile(diffs, 0.025, na.rm = TRUE)),
    rmst_diff_ci_upper = unname(quantile(diffs, 0.975, na.rm = TRUE)),
    rmst_boot_n = length(diffs)
  )
}

# CH24-Q5: summary-scale helpers only; no model or outcome definition changes.
ch24_hr_to_rr <- function(h, mode = "common_outcome") {
  stopifnot(mode %in% c("legacy", "common_outcome"),
            all(is.finite(h)), all(h > 0))
  if (mode == "legacy") return(h)
  -expm1(log(0.5) * sqrt(h)) / -expm1(log(0.5) / sqrt(h))
}

ch24_rr_to_hr <- function(r, mode = "common_outcome") {
  stopifnot(mode %in% c("legacy", "common_outcome"),
            all(is.finite(r)), all(r > 0))
  if (mode == "legacy") return(r)
  vapply(r, function(value) {
    if (value == 1) return(1)
    # Reciprocal symmetry keeps root finding on log(HR) >= 0.
    direction <- if (value < 1) -1 else 1
    log_target <- abs(log(value))
    objective <- function(x) log(ch24_hr_to_rr(exp(x))) - log_target
    upper <- 1
    while (objective(upper) < 0) {
      upper <- upper * 2
      if (upper > 512) stop("HR inverse bracket exceeded finite range")
    }
    root <- uniroot(objective, c(0, upper), tol = 1e-12)$root
    exp(direction * root)
  }, numeric(1), USE.NAMES = FALSE)
}

evalue_from_hr <- function(hr, lo, hi, mode = "common_outcome", true = 1) {
  stopifnot(length(hr) == 1L, length(lo) == 1L, length(hi) == 1L,
            length(true) == 1L, lo <= hr, hr <= hi)
  rr <- ch24_hr_to_rr(c(hr, lo, hi, true), mode)
  evalue_one <- function(q) q + sqrt(q * (q - 1))
  ratio <- function(x) max(x / rr[4], rr[4] / x)
  e_point <- evalue_one(ratio(rr[1]))
  if (lo <= true && hi >= true) {
    e_ci <- 1
  } else {
    rr_ci <- if (hi < true) rr[3] else rr[2]
    e_ci <- evalue_one(ratio(rr_ci))
  }
  c(e_value_point = e_point, e_value_ci_bound = e_ci)
}

run_outcome <- function(dat, label, rmst_boot = 1000) {
  dat <- dat %>% filter(!is.na(follow_days), !is.na(event), !is.na(ipcw_w_trim))
  fit <- coxph(
    Surv(follow_days, event) ~ trt,
    data = dat,
    weights = ipcw_w_trim,
    cluster = stay_id,
    robust = TRUE,
    ties = "efron"
  )
  s <- summary(fit)
  hr <- s$coefficients["trt", "exp(coef)"]
  lo <- s$conf.int["trt", "lower .95"]
  hi <- s$conf.int["trt", "upper .95"]
  p <- s$coefficients["trt", "Pr(>|z|)"]
  ph_p <- tryCatch(cox.zph(fit)$table["GLOBAL", "p"], error = function(e) NA_real_)

  dA <- dat[dat$strategy == "A_early", ]
  dB <- dat[dat$strategy == "B_deferred", ]
  rmst_A <- rmst_wkm(dA$follow_days, dA$event, dA$ipcw_w_trim)
  rmst_B <- rmst_wkm(dB$follow_days, dB$event, dB$ipcw_w_trim)
  boot <- boot_rmst_diff(dat, B = rmst_boot)
  ev <- evalue_from_hr(hr, lo, hi)

  tibble(
    analysis = label,
    n_patients = n_distinct(dat$stay_id),
    clone_rows = nrow(dat),
    early_n = n_distinct(dat$stay_id[dat$strategy == "A_early" & dat$early_crrt]),
    events = sum(dat$event, na.rm = TRUE),
    weighted_hr = hr,
    ci_lower = lo,
    ci_upper = hi,
    p_value = p,
    ph_global_p = ph_p,
    rmst_early = rmst_A,
    rmst_deferred = rmst_B,
    rmst_diff = rmst_A - rmst_B,
    rmst_diff_boot_mean = boot["rmst_diff_boot_mean"],
    rmst_diff_ci_lower = boot["rmst_diff_ci_lower"],
    rmst_diff_ci_upper = boot["rmst_diff_ci_upper"],
    rmst_boot_n = boot["rmst_boot_n"],
    e_value_point = ev["e_value_point"],
    e_value_ci_bound = ev["e_value_ci_bound"]
  )
}

results <- bind_rows(
  run_outcome(ccw, "Full strictK3 primary cohort", rmst_boot = 1000),
  run_outcome(filter(ccw, equipoise %in% TRUE), "Primary SOFA 8-14 equipoise", rmst_boot = 1000),
  run_outcome(filter(ccw, !is.na(sofa_t0) & sofa_t0 >= 9 & sofa_t0 <= 13), "Sensitivity SOFA 9-13", rmst_boot = 1000)
)

write_csv(results, file.path(out_dir, "strictK3_primary_mortality_results.csv"))
saveRDS(results, file.path(out_dir, "strictK3_primary_mortality_results.rds"))

fmt <- results %>%
  mutate(
    hr_ci = sprintf("%.3f (%.3f to %.3f)", weighted_hr, ci_lower, ci_upper),
    p_text = if_else(p_value < 0.001, "<0.001", sprintf("%.3f", p_value)),
    rmst_text = sprintf("%.2f (%.2f to %.2f)", rmst_diff, rmst_diff_ci_lower, rmst_diff_ci_upper),
    e_text = sprintf("%.2f / %.2f", e_value_point, e_value_ci_bound)
  )

report <- c(
  "# Strict KDIGO3 Primary Mortality Results",
  "",
  "Scope: IPCW-weighted Cox and 28-day weighted-KM RMST only. Secondary competing-risk and sensitivity variants remain separate steps.",
  "",
  "| analysis | n patients | early n | events(clone rows) | IPCW HR (95% CI) | p | RMST diff days (95% CI) | E-value point / CI-bound |",
  "|---|---:|---:|---:|---:|---:|---:|---:|",
  apply(fmt, 1, function(x) sprintf(
    "| %s | %s | %s | %s | %s | %s | %s | %s |",
    x[["analysis"]], x[["n_patients"]], x[["early_n"]], x[["events"]],
    x[["hr_ci"]], x[["p_text"]], x[["rmst_text"]], x[["e_text"]]
  )),
  "",
  "Notes:",
  "- HR is Early CRRT vs Deferred CRRT, using IPCW weights and cluster-robust standard errors clustered by stay_id.",
  "- RMST difference is Early minus Deferred over 28 days; CI uses nonparametric bootstrap over stay_id with B=1000.",
  "- E-values use the weighted HR and the confidence-limit closest to the null; if the CI crosses 1, the CI-bound E-value is 1."
)
writeLines(report, file.path(out_dir, "strictK3_primary_mortality_report.md"))

print(results)